CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, wallet TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES customers(id), expires TEXT NOT NULL, mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nonces (id TEXT PRIMARY KEY, wallet TEXT NOT NULL, message TEXT NOT NULL, expires TEXT NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS brand_kits (owner TEXT PRIMARY KEY REFERENCES customers(id), data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS drafts (owner TEXT NOT NULL REFERENCES customers(id), service TEXT NOT NULL, data TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(owner,service));
CREATE TABLE IF NOT EXISTS uploads (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES customers(id), storage_key TEXT NOT NULL, mime TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES customers(id), brief TEXT NOT NULL, brief_hash TEXT NOT NULL, terms_hash TEXT NOT NULL, amount TEXT NOT NULL, expires TEXT NOT NULL, mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES customers(id), quote_id TEXT UNIQUE NOT NULL REFERENCES quotes(id), mode TEXT NOT NULL, brief TEXT NOT NULL, work TEXT NOT NULL, payment TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, funding_expires TEXT NOT NULL, delivery_due TEXT, review_due TEXT, manifest TEXT, manifest_hash TEXT, error TEXT, chain_job TEXT UNIQUE NOT NULL, version INTEGER NOT NULL DEFAULT 1, tx_hash TEXT);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, order_id TEXT UNIQUE NOT NULL REFERENCES orders(id), status TEXT NOT NULL, stage TEXT NOT NULL, lease_token TEXT, lease_until TEXT, attempts INTEGER NOT NULL DEFAULT 0, provider_started INTEGER NOT NULL DEFAULT 0, provider_request_id TEXT, provider_output TEXT, usage TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), stage TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, storage_key TEXT NOT NULL, version INTEGER NOT NULL, UNIQUE(order_id,version,name));
CREATE TABLE IF NOT EXISTS issues (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), owner TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS chain_events (id TEXT PRIMARY KEY, chain_id INTEGER NOT NULL, tx_hash TEXT NOT NULL, log_index INTEGER NOT NULL, block_number TEXT NOT NULL, block_hash TEXT NOT NULL, action TEXT NOT NULL, order_id TEXT NOT NULL REFERENCES orders(id), UNIQUE(chain_id,tx_hash,log_index));
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_owner ON orders(owner);
CREATE INDEX IF NOT EXISTS jobs_status ON jobs(status,lease_until);
CREATE INDEX IF NOT EXISTS events_order ON events(order_id,created_at);
CREATE TABLE IF NOT EXISTS generation_plans (quote_id TEXT PRIMARY KEY REFERENCES quotes(id), engine TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_responses (job_id TEXT PRIMARY KEY REFERENCES jobs(id), response TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_budgets (id TEXT PRIMARY KEY, limit_microusd INTEGER NOT NULL, reserved_microusd INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS provider_budget_reservations (id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES provider_budgets(id), amount_microusd INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operator_tasks (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), action TEXT NOT NULL, status TEXT NOT NULL, policy_id TEXT, gas_reserved_wei TEXT, nonce INTEGER, operator_address TEXT, tx_hash TEXT UNIQUE, signed_tx TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(order_id,action), UNIQUE(operator_address,nonce));
CREATE TABLE IF NOT EXISTS operator_policies (id TEXT PRIMARY KEY, total_wei TEXT NOT NULL, reserved_wei TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operator_locks (address TEXT PRIMARY KEY, token TEXT NOT NULL, expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chain_scan_cursors (order_id TEXT NOT NULL REFERENCES orders(id), event_name TEXT NOT NULL, next_block TEXT NOT NULL, PRIMARY KEY(order_id,event_name));
CREATE TABLE IF NOT EXISTS provider_order_reservations (order_id TEXT PRIMARY KEY REFERENCES orders(id), reservation_id TEXT UNIQUE NOT NULL REFERENCES provider_budget_reservations(id));
CREATE TABLE IF NOT EXISTS worker_health (role TEXT PRIMARY KEY, state TEXT NOT NULL, detail TEXT NOT NULL, updated_at TEXT NOT NULL);
